  const prereqBlock='<div id="plan-prereqs">'+(p.prerequisites.length?p.prerequisites.map((a,i)=>prereqCard(s,a,i)).join(''):'<p class="calc-empty">Kein Kauf vor deinem Ziel. Füge hinzu, was du zuerst kaufen musst (Ausrüstung, Fahrzeug, Immobilie …), falls nötig.</p>')+'</div>'+combobox('plan-prereq-search','Kauf vor dem Ziel hinzufügen (auf der Seite suchen)','plan-prereq')+btn('Eigenen Kauf hinzufügen','data-b-plan-p-add="1"')+'<div class="calc-fields">'+select('plan.strategy','In welcher Reihenfolge kaufen?',Object.entries(STRATEGY_LABEL),p.strategy)+field('plan.situation.upkeepPerSession','Meine Ausgaben pro Session ($): Verbrauchsgüter, Munition …',si.upkeepPerSession,{id:'plan-upkeep',hint:'Wird von deinen Einnahmen abgezogen. Trag 0 ein, wenn du es nicht weißt.'})+'</div>';
  const form='<div class="b-plan-import"><p class="calc-note">Der Businessplan hat eigene Felder: Nichts wird automatisch aus den acht Berechnungen übernommen. Wenn du mit deinen Zahlen aus „Meine Berechnungen“ starten willst, klick hier und ändere dann, was du willst.</p>'+btn('Meine Zahlen aus „Meine Berechnungen“ übernehmen','data-b-plan-import-calcs="1"')+'</div><div class="calc-fields calc-steps">'
   +step(1,'Was ist dein Ziel?',select('plan.goal.kind','Mein Ziel',Object.entries(KIND_LABEL),g.kind)+goalBlock,'Das Ziel bestimmt alles andere: Ein Kauf hat einen Preis, eine Summe verdienst du nach und nach, eine Freischaltung bekommst du mit Punkten.')
   +step(2,'Wo stehst du?','<div class="calc-fields">'+field('plan.situation.capital','Ich habe schon ($)',si.capital,{id:'plan-capital'})+field('plan.situation.reserve','Geld, das ich zurücklege ($)',si.reserve,{id:'plan-reserve'})+field('plan.situation.dailyMinutes','Eine Session dauert (Minuten)',si.dailyMinutes,{id:'plan-daily',min:1,max:1440,hint:'Der Ablauf wird Session für Session erstellt. Lass das Feld leer, wenn du nicht in Sessions rechnest: Dann bekommst du einen Weg in Spielzeit, ohne Kalender.'})+field('plan.situation.daysPerWeek','Wie viele Tage pro Woche spiele ich?',si.daysPerWeek,{id:'plan-days',min:1,max:7,integer:true})+field('plan.situation.players','Wir sind (Spieler)',si.players??1,{id:'plan-players',min:1,max:100,integer:true,hint:'Eine Mission, die mehr Spieler braucht, als deine Gruppe hat, fliegt aus dem Plan – und das wird angezeigt.'})+'</div>','Mit dem, was du hast, und der Dauer deiner Sessions rechnet der Plan in Sessions, dann in Tagen.')
   +step(3,'Wie verdienst du dein Geld?',select('plan.source','Ich verdiene mein Geld',[['missions','Mit meinen Missionen: Der Plan sagt mir, welche ich mache und in welcher Reihenfolge'],['hourly','Nach und nach: Ich verdiene ungefähr einen festen Betrag pro Stunde']],p.source)+missionsBlock,'Mit deinen Missionen wählt der Plan in jeder Session die aus, die in deiner Zeit am meisten einbringen. Das ist der schnellste Weg, den er findet.')
