   if(curve.length>1)doc+=section('curve','Dein Geld im Verlauf des Plans','Die geplante Kurve'+(p.log.length?' und deine echten Punkte (anklickbar)':'')+' · '+money(r.startCash)+' → '+money(r.finalCash),'',()=>visual.chart('c-plan-curve',{title:'Dein Geld, Session für Session',question:'Wann wird jeder Kauf möglich, und wo stehst du dann?',xTitle:'Spielzeit (Stunden)',yTitle:'Geld in der Tasche ($)',unit:'$',xUnit:'h',area:false,series:[{name:'Geplant mit deinen Zahlen',kind:'forecast',step:true,points:curve.map(pt=>({x:pt.hours,y:pt.cash,label:pt.label,key:pt.purchase}))},...(p.log.length?[{name:'Echt (was du eingetragen hast)',kind:'realized',dots:true,points:p.log.map((e,i)=>({x:e.minutes/60,y:e.capital,label:new Date(e.at).toLocaleDateString('de-DE'),edit:'log:'+i}))}]:[])],thresholds:r.input.reserve>0?[{y:r.input.reserve,label:'Rücklage'}]:[],reading:(flow?'Das Geld springt bei jeder Belohnung auf einmal hoch und fällt bei allen Kosten oder Käufen: Nichts wird geglättet.':'Jede Stufe ist eine Session: Ihr Geld wird am Ende der Session gezählt, Käufe direkt danach inklusive. Der Plan endet nach '+plural(r.totalSessions,' Session',' Sessions')+'.')+lowText(r),note:'Die „echten“ Punkte stammen aus deinen Aktualisierungen; sie sind nicht geglättet. Klick auf einen echten Punkt, um ihn zu korrigieren oder zu entfernen.'}));
   const cal=[...r.purchases.filter(x=>x.atSession).map(x=>['Kaufe „'+x.name+'“','nach Session '+x.atSession,'Tag '+dayOf(x.atSession,dpw),planDate(dayOf(x.atSession,dpw))]),[g.kind==='purchase'?'Kaufe '+goalShort(s):g.kind==='unlock'?'Schalte frei: '+goalShort(s):'Du hast '+goalShort(s),'nach Session '+r.totalSessions,'Tag '+r.days,planDate(r.days)]];
