  doc+='<div class="b-plan-links">'+btn('Meine nächste Session vorbereiten','data-open="session"')+btn('Prüfen, was ein Kauf einbringt','data-open="roi"')+btn('Käufe vergleichen','data-open="compare"')+'</div></div>';
