  const byKey={},existing=new Map(p.prerequisites.map(a=>[a.itemId||a.name,a]));
  s.order.keys.forEach(k=>{const a=B.asset(s,k);if(!a)return;const found=existing.get(a.itemId||a.name);if(found){byKey[k]=found.id;return;}if(p.prerequisites.length>=20)return;const id='p-'+Date.now().toString(36)+'-'+p.prerequisites.length;byKey[k]=id;p.prerequisites.push({...B.copy(B.planPrereqTemplate),id,name:a.name,itemId:a.itemId||'',referencePrice:a.referencePrice??null,price:total(a),boostHourly:boost(a),owned:a.owned===true,usagePerSession:usage(a),requires:[]});});
  s.order.keys.forEach(k=>{const a=B.asset(s,k),pr=p.prerequisites.find(x=>x.id===byKey[k]);if(!a||!pr)return;pr.requires=[...new Set([...(pr.requires||[]),...(a.requires||[]).map(r=>byKey[r]).filter(Boolean)])];});
