  if(mins===null||mins<0||mins>1e5){if(fb)fb.textContent='Gib die gespielte Zeit in Minuten ein (zum Beispiel 60).';$('plan-actual-minutes')?.focus();return true;}
  let unitsNow=null;if(g.kind==='unlock'){const v=parse($('plan-actual-units')?.value);if(v!==null){if(v<0||v>1e12){if(fb)fb.textContent='Gib deine '+g.unitLabel+' als Zahl ein.';$('plan-actual-units')?.focus();return true;}unitsNow=v;}}
